'use strict';
let auditUnlocked=false,auditExpanded=false;
async function auditDigest(password,salt){const bytes=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(salt+password));return Array.from(new Uint8Array(bytes),b=>b.toString(16).padStart(2,'0')).join('');}
function auditLocation(entry){if(entry.location)return entry.location;if(entry.project){const p=[...(state.projects||[]),...(state.deletedProjects||[]).map(x=>x.project)].find(x=>x.id===entry.project);return '庫房管理 > '+(p?.name||entry.project);}return '網站管理';}
function auditRows(){const logs=state.logs||[];if(!logs.length)return '<div class="empty">目前沒有操作紀錄</div>';return logs.map((x,n)=>'<details class="audit-row"><summary><time>'+esc(receiptTime(x.time))+'</time><span class="audit-actor">'+esc(x.actor||'未記錄人員')+'</span><strong>'+esc(x.action||'操作紀錄')+'</strong></summary><div class="audit-row-detail"><span>'+esc(auditLocation(x))+'</span><p>'+esc(x.detail||'')+'</p><button type="button" class="small danger-button" data-delete-audit="'+n+'">刪除</button></div></details>').join('');}
function enhanceAudit(){
 const fold=$('.warehouse-fold'),main=$('main');if(!fold||!main||$('.audit-fold'))return;
 const vault=document.createElement('details');vault.className='workspace audit-fold';vault.open=auditUnlocked&&auditExpanded;vault.innerHTML='<summary><span>'+esc(siteText('auditTitle'))+'</span><small>'+(auditUnlocked?'已解鎖':'需要密碼')+'</small></summary>'+(auditUnlocked?'<div class="audit-body"><p class="muted">'+esc(siteText('auditDescription'))+'</p><div class="admin-actions"><button type="button" id="export-audit-json">'+esc(siteText('auditJsonButton'))+'</button><button type="button" id="export-audit-csv">'+esc(siteText('auditCsvButton'))+'</button><button type="button" id="clear-audit" class="danger-button">'+esc(siteText('auditClearButton'))+'</button><button type="button" id="lock-audit">'+esc(siteText('auditLockButton'))+'</button></div><div class="audit-list">'+auditRows()+'</div></div>':'<div class="audit-locked"><p>'+esc(siteText('auditDescription'))+'</p><button type="button" id="unlock-audit">'+esc(siteText('auditUnlockButton'))+'</button></div>');
 fold.after(vault);
 vault.ontoggle=()=>{if(auditUnlocked){if(vault.open){auditExpanded=true;return;}auditUnlocked=false;auditExpanded=false;render();return;}if(vault.open){vault.open=false;unlockAudit();}};
 $('#unlock-audit')?.addEventListener('click',unlockAudit);
 $('#lock-audit')?.addEventListener('click',()=>{auditUnlocked=false;auditExpanded=false;render();});
 $('#export-audit-json')?.addEventListener('click',()=>{addAudit('輸出資訊庫備份','JSON 格式','資訊庫');downloadJSON(state.logs||[],'資訊庫_操作紀錄備份.json');persist();render();});
 $('#export-audit-csv')?.addEventListener('click',exportAuditCSV);
 $('#clear-audit')?.addEventListener('click',async()=>{if(!(await confirmAction('確定刪除資訊庫內的全部操作紀錄？此動作無法復原，請先輸出備份。')))return;state.logs=[];persist();render();toast('資訊庫紀錄已全部刪除');});
 document.querySelectorAll('[data-delete-audit]').forEach(el=>el.onclick=async()=>{const index=Number(el.dataset.deleteAudit);if(!(await confirmAction('確定刪除這筆操作紀錄？')))return;state.logs.splice(index,1);persist();render();toast('操作紀錄已刪除');});
}
function unlockAudit(){
 if(!state.auditSecurity?.hash){modal('資訊庫尚未設定密碼','<p>請先到管理後台設定資訊庫密碼，設定完成後才能查看操作紀錄。</p><button type="button" id="go-audit-admin">前往管理後台</button>',null);$('#go-audit-admin').onclick=()=>{$('#modal').close();location.hash='admin';renderAdmin();};return;}
 modal('輸入資訊庫密碼',field('密碼','auditPassword','','type="password" required autocomplete="current-password"'),'解鎖',async fd=>{const password=String(fd.get('auditPassword')||''),hash=await auditDigest(password,state.auditSecurity.salt);if(hash!==state.auditSecurity.hash)error('密碼不正確。');auditUnlocked=true;auditExpanded=true;$('#modal').close();render();toast('資訊庫已解鎖');});
}
function setAuditPassword(){
 modal(state.auditSecurity?.hash?'更改資訊庫密碼':'設定資訊庫密碼','<p>這是網站登入之外的第二層畫面鎖。請設定至少 6 個字元的密碼。</p>'+field('新密碼','password','','type="password" required minlength="6" autocomplete="new-password"')+field('再次輸入新密碼','confirm','','type="password" required minlength="6" autocomplete="new-password"'),'儲存密碼',async fd=>{const password=String(fd.get('password')||''),confirmPassword=String(fd.get('confirm')||'');if(password.length<6)error('密碼至少需要 6 個字元。');if(password!==confirmPassword)error('兩次輸入的密碼不同。');const salt=Array.from(crypto.getRandomValues(new Uint8Array(16)),b=>b.toString(16).padStart(2,'0')).join(''),hash=await auditDigest(password,salt);state.auditSecurity={salt,hash};auditUnlocked=false;auditExpanded=false;addAudit('設定／更改資訊庫密碼','密碼已更新','管理後台 > 資訊庫設定');persist();$('#modal').close();renderAdmin();toast('資訊庫密碼已儲存');});
}
async function exportAuditCSV(){if(!await authorizeExport())return;addAudit('輸出資訊庫備份','CSV 格式','資訊庫');const quote=v=>'"'+String(v??'').replaceAll('"','""')+'"',rows=[['時間','操作人員','操作','位置','內容'],...(state.logs||[]).map(x=>[receiptTime(x.time),x.actor||'未記錄人員',x.action,auditLocation(x),x.detail])],csv='\ufeff'+rows.map(r=>r.map(quote).join(',')).join('\r\n'),a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));a.download='資訊庫_操作紀錄.csv';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);persist();render();}
function enhanceAuditAdmin(){const main=$('main');if(!main||$('#audit-settings'))return;const card=document.createElement('section');card.id='audit-settings';card.className='admin-card';card.innerHTML='<h2>'+esc(siteText('auditTitle'))+'設定</h2><p>'+esc(siteText('auditDescription'))+'</p><p class="muted">'+(state.auditSecurity?.hash?'資訊庫密碼已設定。可在這裡重新設定。':'尚未設定密碼，資訊庫目前無法開啟。')+'</p><div class="admin-actions"><button type="button" id="set-audit-password">'+(state.auditSecurity?.hash?'更改資訊庫密碼':'設定資訊庫密碼')+'</button><button type="button" id="edit-audit-words">修改資訊庫文字</button></div>';main.append(card);$('#set-audit-password').onclick=setAuditPassword;$('#edit-audit-words').onclick=()=>editSiteText('audit');}
const renderBeforeAudit=render;render=function(){renderBeforeAudit();enhanceAudit();};
const renderAdminBeforeAudit=renderAdmin;renderAdmin=function(){renderAdminBeforeAudit();enhanceAuditAdmin();};
